INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key)
SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),f.book_id,f.chapter_id,f.topic_id,f.title,f.fact_text,'fact',f.id,'batch0649-0653:fact:'||f.id::text FROM public.gk_facts f WHERE f.source_page BETWEEN 649 AND 653 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0649-0653:fact:'||f.id::text);
INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key)
SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),n.book_id,n.chapter_id,n.topic_id,n.title,n.content,'note',n.id,'batch0649-0653:note:'||n.id::text FROM public.gk_notes n WHERE n.source_page BETWEEN 649 AND 653 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0649-0653:note:'||n.id::text);
INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key)
SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),m.book_id,m.chapter_id,m.topic_id,m.question,'সঠিক উত্তর: '||o.option_key||'. '||o.option_text,'mcq',m.id,'batch0649-0653:mcq:'||m.id::text FROM public.gk_mcqs m JOIN public.gk_mcq_options o ON o.mcq_id=m.id AND o.is_correct WHERE m.source_page BETWEEN 649 AND 653 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0649-0653:mcq:'||m.id::text);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata)
SELECT 'fact',f.id,f.title,f.fact_text,'Status-marked GK fact | source page '||f.source_page::text FROM public.gk_facts f WHERE f.source_page BETWEEN 649 AND 653 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='fact' AND d.entity_id=f.id);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata)
SELECT 'note',n.id,n.title,n.content,'Structured source note | source page '||n.source_page::text FROM public.gk_notes n WHERE n.source_page BETWEEN 649 AND 653 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='note' AND d.entity_id=n.id);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata)
SELECT 'mcq',m.id,NULL,m.question,'Past-exam MCQ | source page '||m.source_page::text||' | question '||m.source_question_number FROM public.gk_mcqs m WHERE m.source_page BETWEEN 649 AND 653 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='mcq' AND d.entity_id=m.id);
COMMIT;